export function float_op_name({ op }) {
  if (op === "+") {
    return "fadd";
  }
  if (op === "-") {
    return "fsub";
  }
  if (op === "*") {
    return "fmul";
  }
  if (op === "/") {
    return "fdiv";
  }
  return "frem";
}

export function fcmp_name({ op }) {
  if (op === "<") {
    return "olt";
  }
  if (op === "<=") {
    return "ole";
  }
  if (op === ">") {
    return "ogt";
  }
  return "oge";
}

export function icmp_name({ op }) {
  if (op === "<") {
    return "slt";
  }
  if (op === "<=") {
    return "sle";
  }
  if (op === ">") {
    return "sgt";
  }
  return "sge";
}

